<script setup lang="ts">
import { shallowRef, watch } from 'vue'
import * as api from '@/api/library'
import MatchCandidates from './MatchCandidates.vue'
import NfoPreview from './NfoPreview.vue'
import ArtworkPreview from './ArtworkPreview.vue'
const props = defineProps<{ itemId: number | null; csrfToken: string; labels: Record<string, string> }>()
const emit = defineEmits<{ close: [] }>()
const detail = shallowRef<{ item: api.MediaItem; metadata: api.Metadata; metadataOrigin: 'draft' | 'nfo' | 'empty'; writable: boolean } | null>(null); const candidates = shallowRef<api.Candidate[]>([]); const error = shallowRef(''); const searching = shallowRef(false); const plan = shallowRef<api.WritePlan | null>(null); const applying = shallowRef(false); const artworkPlan = shallowRef<api.ArtworkPlan | null>(null); const applyingArtwork = shallowRef(false); const draft = shallowRef<api.Metadata | null>(null)
watch(() => props.itemId, async (id) => { detail.value=null; draft.value=null; candidates.value=[]; error.value=''; if (!id) return; try { detail.value=await api.mediaDetail(id); draft.value=structuredClone(detail.value.metadata) } catch (caught) { error.value=caught instanceof Error ? caught.message : 'Unable to load media' } }, { immediate:true })
async function findMatches(){if(!props.itemId)return;searching.value=true;error.value='';try{candidates.value=(await api.candidates(props.itemId)).items}catch(caught){error.value=caught instanceof Error?caught.message:props.labels.configured}finally{searching.value=false}}
async function select(candidate:api.Candidate){if(!props.itemId)return;try{draft.value=await api.selectCandidate(props.csrfToken,props.itemId,candidate.id);candidates.value=[]}catch(caught){error.value=caught instanceof Error?caught.message:'Unable to select candidate'}}
async function save(){if(!props.itemId||!draft.value)return;try{draft.value=await api.saveMetadata(props.csrfToken,props.itemId,draft.value)}catch(caught){error.value=caught instanceof Error?caught.message:'Unable to save draft'}}
async function preview(){if(!props.itemId||!draft.value)return;try{plan.value=await api.previewNfo(props.csrfToken,props.itemId,draft.value)}catch(caught){error.value=caught instanceof Error?caught.message:'Unable to create preview'}}
async function apply(){if(!plan.value)return;applying.value=true;try{await api.applyNfo(props.csrfToken,plan.value.id);plan.value=null}catch(caught){error.value=caught instanceof Error?caught.message:'Unable to write NFO'}finally{applying.value=false}}
async function previewArtwork(){if(!props.itemId||!draft.value)return;try{artworkPlan.value=await api.previewArtwork(props.csrfToken,props.itemId,draft.value)}catch(caught){error.value=caught instanceof Error?caught.message:'Unable to create artwork preview'}}
async function applyArtwork(){if(!artworkPlan.value)return;applyingArtwork.value=true;try{await api.applyArtwork(props.csrfToken,artworkPlan.value.id);artworkPlan.value=null}catch(caught){error.value=caught instanceof Error?caught.message:'Unable to download artwork'}finally{applyingArtwork.value=false}}
</script>
<template><aside class="inspector"><template v-if="detail && draft"><header class="inspector-header"><button class="mobile-back" type="button" @click="emit('close')">← {{ labels.library }}</button><p class="eyebrow">{{ labels.details }}</p><h2>{{ detail.item.titleHint }}</h2><small>{{ detail.item.relativePath }}</small></header><p v-if="detail.metadataOrigin === 'nfo'" class="origin">Loaded from existing Kodi NFO · 已从现有 Kodi NFO 读取</p><p v-if="error" class="error">{{ error }}</p><div class="actions"><button type="button" :disabled="searching" @click="findMatches">{{ labels.search }}</button><button type="button" :disabled="!detail.writable" @click="save">{{ labels.save }}</button><button type="button" :disabled="!detail.writable" @click="preview">{{ labels.preview }}</button><button type="button" :disabled="!detail.writable" @click="previewArtwork">{{ labels.artwork }}</button></div><p v-if="!detail.writable" class="read-only">{{ labels.readOnly }}</p><MatchCandidates :candidates="candidates" :busy="searching" @select="select"/><form class="editor" @submit.prevent="save"><label>Title<input v-model="draft.title" required /></label><label>Original title<input v-model="draft.originalTitle" /></label><label>Year<input v-model.number="draft.year" type="number" min="1888" max="2100" /></label><label>Genres<input :value="(draft.genres ?? []).join(', ')" @input="draft.genres=($event.target as HTMLInputElement).value.split(',').map(value=>value.trim()).filter(Boolean)" /></label><label>Overview<textarea v-model="draft.overview" rows="5" /></label></form></template><div v-else class="inspector-empty"><p class="eyebrow">{{ labels.details }}</p><h2>{{ labels.noMatch }}</h2><p>Select a film from the list to inspect local NFO data or find a TMDb match.</p></div></aside><NfoPreview :plan="plan" :applying="applying" @apply="apply" @close="plan=null" /><ArtworkPreview :plan="artworkPlan" :applying="applyingArtwork" :labels="labels" @apply="applyArtwork" @close="artworkPlan=null" /></template>
<style scoped>.inspector{display:grid;align-content:start;gap:1rem;min-width:0;min-height:32rem;padding:clamp(1.1rem,2vw,1.8rem);border:1px solid var(--mist-300);border-radius:.9rem;background:var(--paper)}.inspector h2{margin:.3rem 0;font:500 2rem/1 var(--font-display)}.inspector small{color:var(--ink-600);overflow-wrap:anywhere}.actions{display:flex;flex-wrap:wrap;gap:.5rem}.actions button{min-height:2.5rem;padding:.5rem .7rem;border:1px solid var(--ink-700);border-radius:.4rem;background:var(--ink-900);color:white;font-weight:700;cursor:pointer}.actions button:disabled{opacity:.5}.editor{display:grid;gap:.7rem}.editor label{display:grid;gap:.25rem;font-size:.8rem;font-weight:700}.editor input,.editor textarea{width:100%;padding:.55rem .65rem;border:1px solid var(--mist-300);border-radius:.4rem;background:white}.error,.read-only,.origin{margin:0;padding:.6rem;border-radius:.4rem}.error{background:#f9e1d6;color:#8b2d17}.read-only,.origin{background:var(--water-100);color:var(--ink-800)}.inspector-empty{align-self:center;max-width:24rem;color:var(--ink-600)}.inspector-empty h2{color:var(--ink-900)}.mobile-back{display:none}.mobile-back{min-height:2.4rem;padding:.4rem .6rem;border:0;background:transparent;color:var(--ink-700);font-weight:700;cursor:pointer}@media(max-width:760px){.mobile-back{display:block}.inspector{min-height:100vh;border:0;border-radius:0;padding:1.25rem}.inspector-empty{display:none}}</style>
